import { AddRunbookVariable1804050000000 } from "../../../../Server/Infrastructure/Postgres/SchemaMigrations/1804050000000-AddRunbookVariable";
import SchemaMigrations from "../../../../Server/Infrastructure/Postgres/SchemaMigrations/Index";
import { MigrationInterface, QueryRunner } from "typeorm";
import fs from "fs";
import path from "path";
import { describe, expect, test } from "@jest/globals";

/*
 * The runbook variables' migration, generated by TypeORM against a fully
 * migrated throwaway database (and checked for drift against it): two new
 * tables - RunbookVariable, and the Runners a secret reaches
 * (RunbookVariableRunner) - and nothing else. Every index is built and every
 * key checked on an empty table, so no table a project already has is
 * scanned or locked for long; the old secrets table is left as it is, for
 * the Workers' data migration to read.
 */

const TRAILING_TIMESTAMP_PATTERN: RegExp = /(\d+)$/;

type MigrationClass = new () => MigrationInterface;

async function record(direction: "up" | "down"): Promise<Array<string>> {
  const steps: Array<string> = [];

  const runner: QueryRunner = {
    isTransactionActive: true,
    query: async (sql: string): Promise<void> => {
      steps.push(sql);
    },
  } as unknown as QueryRunner;

  const migration: AddRunbookVariable1804050000000 =
    new AddRunbookVariable1804050000000();

  if (direction === "up") {
    await migration.up(runner);
  } else {
    await migration.down(runner);
  }

  return steps;
}

function timestampOf(migration: MigrationClass): number {
  const match: RegExpMatchArray | null = migration.name.match(
    TRAILING_TIMESTAMP_PATTERN,
  );

  return match ? parseInt(match[1]!, 10) : 0;
}

// The table a statement creates or alters.
function tableOf(statement: string): string {
  for (const prefix of ["CREATE TABLE ", "ALTER TABLE ", "DROP TABLE "]) {
    if (statement.startsWith(prefix)) {
      return statement.slice(prefix.length).split(" ")[0]!.split('"').join("");
    }
  }

  const on: number = statement.indexOf(" ON ");

  return on === -1
    ? ""
    : statement
        .slice(on + 4)
        .split(" ")[0]!
        .split('"')
        .join("");
}

describe("the runbook variables' migration", () => {
  test("names itself after its timestamp", () => {
    expect(new AddRunbookVariable1804050000000().name).toBe(
      "AddRunbookVariable1804050000000",
    );
  });

  test("is registered once, after every older migration", () => {
    const registered: Array<MigrationClass> =
      SchemaMigrations as Array<MigrationClass>;

    expect(
      registered.filter((candidate: MigrationClass) => {
        return candidate === AddRunbookVariable1804050000000;
      }),
    ).toHaveLength(1);

    const index: number = registered.indexOf(
      AddRunbookVariable1804050000000 as MigrationClass,
    );

    for (let before: number = 0; before < index; before++) {
      expect(timestampOf(registered[before]!)).toBeLessThan(
        timestampOf(AddRunbookVariable1804050000000 as MigrationClass),
      );
    }
  });

  test("is backed by exactly one file carrying its timestamp", () => {
    const directory: string = path.join(
      __dirname,
      "../../../../Server/Infrastructure/Postgres/SchemaMigrations",
    );

    expect(
      fs.readdirSync(directory).filter((file: string) => {
        return file.startsWith("1804050000000-");
      }),
    ).toEqual(["1804050000000-AddRunbookVariable.ts"]);
  });

  test("makes the two tables, and touches no other table", async () => {
    const up: Array<string> = await record("up");

    expect(
      up
        .filter((statement: string): boolean => {
          return statement.startsWith("CREATE TABLE ");
        })
        .map(tableOf),
    ).toEqual(["RunbookVariable", "RunbookVariableRunner"]);

    for (const statement of up) {
      expect({
        statement,
        table: ["RunbookVariable", "RunbookVariableRunner"].includes(
          tableOf(statement),
        ),
      }).toEqual({ statement, table: true });
    }

    // The old secrets are left for the data migration to read.
    expect(up.join("\n")).not.toContain('"RunbookSecret"');
  });

  test("a variable is plain until made a secret, and no global Runner uses a secret until someone says so", async () => {
    const create: string = (await record("up"))[0]!;

    expect(create).toContain('"isSecret" boolean NOT NULL DEFAULT false');
    expect(create).toContain(
      '"isAvailableToGlobalRunners" boolean NOT NULL DEFAULT false',
    );
    expect(create).toContain('"secretValue" text');
    expect(create).toContain('"runbookId" uuid,');
    expect(create).toContain('"projectId" uuid NOT NULL');
  });

  test("a variable goes with its project or its runbook, and a Runner's assignment with the Runner", async () => {
    const up: Array<string> = await record("up");

    expect(up).toContain(
      `ALTER TABLE "RunbookVariable" ADD CONSTRAINT "FK_8317da94785de787ce004a0f16b" FOREIGN KEY ("projectId") REFERENCES "Project"("_id") ON DELETE CASCADE ON UPDATE NO ACTION`,
    );
    expect(up).toContain(
      `ALTER TABLE "RunbookVariable" ADD CONSTRAINT "FK_501810d15edfa564181070ba615" FOREIGN KEY ("runbookId") REFERENCES "Runbook"("_id") ON DELETE CASCADE ON UPDATE NO ACTION`,
    );
    expect(up).toContain(
      `ALTER TABLE "RunbookVariableRunner" ADD CONSTRAINT "FK_addd5a3968c71e3a3b090ade5ce" FOREIGN KEY ("runnerId") REFERENCES "Runner"("_id") ON DELETE CASCADE ON UPDATE CASCADE`,
    );
  });

  test("down() drops what up() made, the keys first", async () => {
    const down: Array<string> = await record("down");

    expect(down[down.length - 1]).toBe(`DROP TABLE "RunbookVariable"`);
    expect(down).toContain(`DROP TABLE "RunbookVariableRunner"`);
    expect(down.indexOf(`DROP TABLE "RunbookVariableRunner"`)).toBeLessThan(
      down.indexOf(`DROP TABLE "RunbookVariable"`),
    );
    expect(
      down.slice(0, 6).every((statement: string): boolean => {
        return statement.includes("DROP CONSTRAINT");
      }),
    ).toBe(true);
  });
});
